use std::collections::HashMap;
use std::sync::LazyLock;

/// Lowercased chapter name → genre labels. Generated by `scripts/genres.ts`
/// and hand-editable; the archive itself carries no genre data.
static GENRES: LazyLock<HashMap<String, Vec<String>>> = LazyLock::new(|| {
    serde_json::from_str(include_str!("../../data/genres.json"))
        .expect("data/genres.json is a map of game name to genre labels")
});

pub fn genres_for(game_name: &str) -> &'static [String] {
    GENRES
        .get(&game_name.to_lowercase())
        .map_or(&[], Vec::as_slice)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_genre_file_parses_and_is_non_empty() {
        assert!(!GENRES.is_empty());
    }

    #[test]
    fn genre_lookup_ignores_case() {
        assert_eq!(genres_for("Just Chatting"), genres_for("just chatting"));
        assert!(!genres_for("JUST CHATTING").is_empty());
    }

    #[test]
    fn unknown_game_has_no_genres() {
        assert!(genres_for("definitely not a real game title").is_empty());
    }

    #[test]
    fn every_key_is_lowercase_and_every_game_has_a_genre() {
        for (name, genres) in GENRES.iter() {
            assert_eq!(name, &name.to_lowercase(), "key must be lowercase: {name}");
            assert!(!genres.is_empty(), "{name} has an empty genre list");
        }
    }
}
